void Solver::bump_var(int var, double coeff) {
    // add activity increment
    double delta = var_inc * coeff;
    activity[var] += delta;

    // lazy global rescaling to avoid overflow of activity values or var_inc
    const double ACT_THRESH = 1e100;
    const double VARINC_THRESH = 1e50;
    const double SCALE = 1e-100;
    if (activity[var] > ACT_THRESH || var_inc > VARINC_THRESH) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
